{
  "tools": [
    {
      "name": "search_docs",
      "description": "Use this instead of Grep to search the team's published documentation: runbooks, API guides and architecture notes that are not in the repository. Use it when the question is about how a service behaves or how to operate it, and use Grep for code in the checkout. It takes a plain-language query such as 'refund retry policy' or an exact page title, and returns up to ten matches, each with the page title, a link and a short excerpt. It does not search the source code, and it does not return whole pages: open a link for that.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {"type": "string", "description": "What to look for, in plain language or as an exact page title."},
          "limit": {"type": "integer", "description": "How many matches to return, from 1 to 10. The default is 10."}
        },
        "required": ["query"]
      }
    }
  ]
}

